const taka = n => '৳' + Math.round(n).toLocaleString('en-IN');
const productById = id => PRODUCTS.find(p => p.id === id);
const sellerById = id => SELLERS.find(s => s.id === id);
const catById = id => CATEGORIES.find(c => c.id === id);
const customerById = id => CUSTOMERS.find(c => c.id === id);
const discount = p => p.old > p.price ? Math.round((1 - p.price / p.old) * 100) : 0;

// Changes made in the admin panel are stored in this browser (localStorage "bz_admin")
// and applied here, so the storefront and admin stay in sync in the demo.
(function applyAdminChanges() {
  let S; try { S = JSON.parse(localStorage.getItem('bz_admin')) || {}; } catch (e) { S = {}; }
  (S.newProducts || []).forEach(p => { if (!PRODUCTS.find(x => x.id === p.id)) PRODUCTS.unshift(p); });
  for (let k = PRODUCTS.length - 1; k >= 0; k--) {
    const p = PRODUCTS[k];
    if ((S.deleted || []).includes(p.id)) { PRODUCTS.splice(k, 1); continue; }
    if (S.products && S.products[p.id]) Object.assign(p, S.products[p.id]);
  }
  SELLERS.forEach(s => { if (S.vendors && S.vendors[s.id]) s.status = S.vendors[s.id]; if (S.commission && S.commission[s.id]) s.commission = S.commission[s.id]; });
  ORDERS.forEach(o => { if (S.orders && S.orders[o.id]) o.status = S.orders[o.id]; });
  CUSTOMERS.forEach(c => { if (S.customers && S.customers[c.id]) c.status = S.customers[c.id]; });
  (S.cats || []).forEach(c => { if (!CATEGORIES.find(x => x.id === c.id)) CATEGORIES.push(c); });
  SELLERS.forEach(s => { s.products = PRODUCTS.filter(p => p.seller === s.id).length; });
})();
// A product is shown in the store only if it is visible and its vendor is active
const isLive = p => p.status === 'active' && (sellerById(p.seller) || {}).status === 'active';
